import { apiGet } from '../../lib/api/client.js'
import { renderTable } from '../../lib/output/table.js'
import { formatDate, formatRelative } from '../../lib/utils/format.js'

interface SessionInfo {
  id: string
  device_fingerprint: string
  platform: string
  last_seen: string
  created_at: string
  current: boolean
}

export default async function authSessions(): Promise<void> {
  const data = await apiGet<{ sessions: SessionInfo[] }>('/api/auth/ssp/sessions', { authenticated: true })
  const rows = (data.sessions || []).map(s => ({
    id: s.id.slice(0, 8) + '...',
    device: s.device_fingerprint.slice(0, 12),
    platform: s.platform || 'unknown',
    last_seen: formatRelative(s.last_seen),
    created: formatDate(s.created_at),
    current: s.current ? '●' : '',
  }))
  console.log(renderTable(rows, [
    { key: 'id', label: 'Session ID' },
    { key: 'device', label: 'Fingerprint' },
    { key: 'platform', label: 'Platform' },
    { key: 'last_seen', label: 'Last Seen' },
    { key: 'created', label: 'Created' },
    { key: 'current', label: '' },
  ]))
}
